fn p_wage_new_rate_record(state: &mut ProgramState) {
}

/// 0000-MAINLINE-CONTROL
fn p_0000_mainline_control(state: &mut ProgramState) {
    p_0100_initial_routine(state);
    if state.pps_data_all.pps_rtc == 00 {
        p_1000_edit_the_bill_info(state);
    }
    if state.pps_data_all.pps_rtc == 00 {
        p_2000_assemble_pps_variables(state);
        p_3000_calc_payment(state);
    }
    p_9000_move_results(state);
    return;
}

/// 0100-INITIAL-ROUTINE
fn p_0100_initial_routine(state: &mut ProgramState) {
    state.pps_data_all = Default::default();
    state.bill_new_data.bill_data_test = Default::default();
    state.hold_pps_components = Default::default();
    state.pps_data_all.pps_rtc = 0;
    state.pps_data_all.pps_data.pps_calc_vers_cd = FixedString::copy_from(&state.cal_version);
    if &format!("{}", state.bill_new_data.provider_specific_file_portion.p_prov_type) == &"40".to_string() {
        state.pps_data_all.pps_other_data.pps_nat_labor_pct = Decimal::from(0i64);
        state.pps_data_all.pps_other_data.pps_nat_nonlabor_pct = Decimal::from(0i64);
        state.pps_data_all.pps_data.pps_wage_adj_rate = Decimal::from_i64(state.wage_new_rate_record.w_new_rate1_record.value, state.wage_new_rate_record.w_new_rate1_record.scale);
        state.bill_new_data.bill_data_test.msa_wage_amt = Decimal::from_i64(state.wage_new_rate_record.w_new_rate1_record.value, state.wage_new_rate_record.w_new_rate1_record.scale);
    } else {
        if &format!("{}", state.bill_new_data.provider_specific_file_portion.p_prov_type) == &"41".to_string() {
            state.pps_data_all.pps_other_data.pps_nat_labor_pct = Decimal::from(0i64);
            state.pps_data_all.pps_other_data.pps_nat_nonlabor_pct = Decimal::from(0i64);
            state.pps_data_all.pps_data.pps_wage_adj_rate = Decimal::from_i64(state.wage_new_rate_record.w_new_rate2_record.value, state.wage_new_rate_record.w_new_rate2_record.scale);
            state.bill_new_data.bill_data_test.msa_wage_amt = Decimal::from_i64(state.wage_new_rate_record.w_new_rate2_record.value, state.wage_new_rate_record.w_new_rate2_record.scale);
        } else {
            state.pps_data_all.pps_rtc = 52 as u32;
            state.pps_data_all.pps_data.pps_wage_adj_rate = Decimal::from(0i64);
        }
    }
    state.pps_data_all.msa_adj_year_amt = Decimal::from_i64(state.pps_data_all.pps_data.pps_wage_adj_rate.value, state.pps_data_all.pps_data.pps_wage_adj_rate.scale);
    state.pps_data_all.pps_other_data.pps_bdgt_neut_rate = Decimal::from_i64(state.case_mix_bdgt_neut_factor.value, state.case_mix_bdgt_neut_factor.scale);
    state.hold_pps_components.h_drug_addon = Decimal::from_i64(state.drug_addon.value, state.drug_addon.scale);
}

