/// 2000-ASSEMBLE-PPS-VARIABLES
fn p_2000_assemble_pps_variables(state: &mut ProgramState) {
    state.hold_pps_components.h_wage_adj_pymt_amt = Decimal::from_i64(state.pps_data_all.pps_data.pps_wage_adj_rate.value, state.pps_data_all.pps_data.pps_wage_adj_rate.scale);
    state.hold_pps_components.h_bsa = Decimal::from(((0i64)) as i64);
    state.hold_pps_components.h_bmi = Decimal::from(i64::from((state.bill_new_data.bill_portion.b_patient_wgt / (state.bill_new_data.bill_portion.b_patient_hgt.pow(2))) * 10000));
    if state.hold_pps_components.h_patient_age > 17 {
        state.hold_pps_components.h_bsa_factor = Decimal::from((1) as i64);
    }
    // SKIP: unresolved condition
}

/// 3000-CALC-PAYMENT
fn p_3000_calc_payment(state: &mut ProgramState) {
    state.hold_pps_components.h_pymt_amt = Decimal::from(i64::from(state.hold_pps_components.h_wage_adj_pymt_amt * state.hold_pps_components.h_bmi_factor * state.hold_pps_components.h_bsa_factor * state.pps_data_all.pps_other_data.pps_bdgt_neut_rate * state.hold_pps_components.h_age_factor * state.hold_pps_components.h_drug_addon));
    state.bill_new_data.bill_data_test.case_mix_fctr_adj_rate = Decimal::from_i64(state.hold_pps_components.h_pymt_amt.value, state.hold_pps_components.h_pymt_amt.scale);
    state.bill_new_data.bill_data_test.cond_cd_73 = Default::default();
    // SKIP: unresolved condition
    state.hold_pps_components.h_pymt_amt = Decimal::from(i64::from(state.hold_pps_components.h_pymt_amt + state.hemo_peri_ccpd_amt));
    state.bill_new_data.bill_data_test.cond_cd_73.amt_indic = "A".into();
    state.bill_new_data.bill_data_test.cond_cd_73.blood_dollar = state.hemo_peri_ccpd_amt as u32;
    // SKIP: unresolved condition
    state.hold_pps_components.h_pymt_amt = Decimal::from(i64::from(state.hold_pps_components.h_pymt_amt + state.capd_amt));
    state.bill_new_data.bill_data_test.cond_cd_73.amt_indic = "A".into();
    state.bill_new_data.bill_data_test.cond_cd_73.blood_dollar = state.capd_amt as u32;
    // SKIP: unresolved condition
    state.hold_pps_components.h_pymt_amt = Decimal::from(i64::from(state.hold_pps_components.h_pymt_amt * state.capd_or_ccpd_factor));
    state.bill_new_data.bill_data_test.cond_cd_74.hemo_ccpd_capd = Decimal::from_i64(state.capd_or_ccpd_factor.value, state.capd_or_ccpd_factor.scale);
    state.bill_new_data.bill_data_test.cond_cd_73.amt_indic = "A".into();
    state.bill_new_data.bill_data_test.cond_cd_73.blood_dollar = 0;
    state.pps_data_all.pps_data.pps_final_pay_amt = Decimal::from_i64(state.hold_pps_components.h_pymt_amt.value, state.hold_pps_components.h_pymt_amt.scale);
    state.pps_data_all.pps_data.pps_wage_adj_rate = Decimal::from(0i64);
}

/// 9000-MOVE-RESULTS
fn p_9000_move_results(state: &mut ProgramState) {
    if state.pps_data_all.pps_rtc < 50 {
        state.pps_data_all.pps_data.pps_cond_code = FixedString::copy_from(&state.bill_new_data.bill_portion.b_cond_code);
        state.pps_data_all.pps_data.pps_rev_code = FixedString::copy_from(&state.bill_new_data.bill_portion.b_rev_code);
        state.pps_data_all.pps_data.pps_msa = FixedString::copy_from(&state.bill_new_data.provider_specific_file_portion.p_geo_msa);
        state.pps_data_all.pps_data.pps_cbsa = FixedString::copy_from(&state.bill_new_data.provider_specific_file_portion.p_geo_cbsa);
        state.pps_data_all.pps_other_data.pps_age_factor = Decimal::from_i64(state.hold_pps_components.h_age_factor.value, state.hold_pps_components.h_age_factor.scale);
        state.pps_data_all.pps_other_data.pps_bsa_factor = Decimal::from_i64(state.hold_pps_components.h_bsa_factor.value, state.hold_pps_components.h_bsa_factor.scale);
        state.pps_data_all.pps_other_data.pps_bmi_factor = Decimal::from_i64(state.hold_pps_components.h_bmi_factor.value, state.hold_pps_components.h_bmi_factor.scale);
        // SKIP: unresolved condition
    } else {
        // SKIP: unresolved condition
    }
}

